// Generic single-input/single-output tensor probe for experiment 0010 taps.
// QNN mode always disables implicit CPU EP fallback.
#include <chrono>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>
#include "onnxruntime_cxx_api.h"

namespace {
struct Args { std::string model,input,output,provider,backend,profile; int runs=1; };
Args Parse(int argc,char** argv){ Args a; auto take=[&](int& i){if(++i>=argc)throw std::runtime_error("missing value");return std::string(argv[i]);}; for(int i=1;i<argc;++i){std::string k=argv[i]; if(k=="--model")a.model=take(i);else if(k=="--input")a.input=take(i);else if(k=="--output")a.output=take(i);else if(k=="--provider")a.provider=take(i);else if(k=="--backend")a.backend=take(i);else if(k=="--profile-prefix")a.profile=take(i);else if(k=="--runs")a.runs=std::stoi(take(i));else throw std::runtime_error("unknown argument: "+k);} if(a.model.empty()||a.input.empty()||a.output.empty()||(a.provider!="cpu"&&a.provider!="qnn")||a.runs<1)throw std::runtime_error("missing or invalid required arguments"); if(a.provider=="qnn"&&(a.backend.empty()||a.profile.empty()))throw std::runtime_error("QNN requires backend and profile prefix"); return a; }
size_t Count(const std::vector<int64_t>& shape){size_t n=1;for(auto d:shape){if(d<=0)throw std::runtime_error("model shape is not concrete");n*=static_cast<size_t>(d);}return n;}
std::vector<float> Read(const std::string& p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||static_cast<size_t>(f.tellg())!=n*sizeof(float))throw std::runtime_error("input byte count mismatch");f.seekg(0);std::vector<float> v(n);if(!f.read(reinterpret_cast<char*>(v.data()),n*sizeof(float)))throw std::runtime_error("input read failed");return v;}
void Write(const std::string& p,const float* x,size_t n){std::filesystem::create_directories(std::filesystem::path(p).parent_path());std::ofstream f(p,std::ios::binary|std::ios::trunc);if(!f.write(reinterpret_cast<const char*>(x),n*sizeof(float)))throw std::runtime_error("output write failed");}
double Seconds(std::chrono::steady_clock::time_point s){return std::chrono::duration<double>(std::chrono::steady_clock::now()-s).count();}
std::string ShapeJson(const std::vector<int64_t>& s){std::string x="[";for(size_t i=0;i<s.size();++i){if(i)x+=",";x+=std::to_string(s[i]);}return x+"]";}
}
int main(int argc,char** argv){try{auto a=Parse(argc,argv);Ort::Env env(ORT_LOGGING_LEVEL_INFO,"0010-tensor-probe");Ort::SessionOptions o;o.SetIntraOpNumThreads(1);o.SetInterOpNumThreads(1);o.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);o.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);if(a.provider=="qnn"){o.AddConfigEntry("session.disable_cpu_ep_fallback","1");o.EnableProfiling(a.profile.c_str());const std::unordered_map<std::string,std::string> po={{"backend_path",a.backend},{"profiling_level","detailed"},{"profiling_file_path",a.profile+".qnn.csv"},{"offload_graph_io_quantization","0"},{"htp_performance_mode","burst"},{"soc_model","43"}};o.AppendExecutionProvider("QNN",po);}auto start=std::chrono::steady_clock::now();Ort::Session s(env,a.model.c_str(),o);double create=Seconds(start);if(s.GetInputCount()!=1||s.GetOutputCount()!=1)throw std::runtime_error("probe requires one input and one output");auto in_shape=s.GetInputTypeInfo(0).GetTensorTypeAndShapeInfo().GetShape();size_t in_count=Count(in_shape);auto values=Read(a.input,in_count);Ort::AllocatorWithDefaultOptions alloc;auto in_name=s.GetInputNameAllocated(0,alloc);auto out_name=s.GetOutputNameAllocated(0,alloc);auto mem=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);auto tensor=Ort::Value::CreateTensor<float>(mem,values.data(),values.size(),in_shape.data(),in_shape.size());const char* ins[]={in_name.get()};const char* outs[]={out_name.get()};std::vector<Ort::Value> result;double first=0,warm=0;for(int i=0;i<a.runs;++i){start=std::chrono::steady_clock::now();result=s.Run(Ort::RunOptions{nullptr},ins,&tensor,1,outs,1);double t=Seconds(start);if(i==0)first=t;else warm+=t;}auto info=result[0].GetTensorTypeAndShapeInfo();auto out_shape=info.GetShape();size_t out_count=info.GetElementCount();Write(a.output,result[0].GetTensorData<float>(),out_count);std::string profile_path;if(a.provider=="qnn"){auto p=s.EndProfilingAllocated(alloc);profile_path=p.get();}std::cout<<"{\n  \"result\": \"passed\",\n  \"provider\": \""<<a.provider<<"\",\n  \"runtime\": \""<<OrtGetApiBase()->GetVersionString()<<"\",\n  \"input_name\": \""<<in_name.get()<<"\",\n  \"input_shape\": "<<ShapeJson(in_shape)<<",\n  \"output_name\": \""<<out_name.get()<<"\",\n  \"output_shape\": "<<ShapeJson(out_shape)<<",\n  \"output_elements\": "<<out_count<<",\n  \"session_create_seconds\": "<<create<<",\n  \"first_run_seconds\": "<<first<<",\n  \"warm_mean_seconds\": "<<(a.runs>1?warm/(a.runs-1):0)<<",\n  \"profile_path\": \""<<profile_path<<"\"\n}\n";return 0;}catch(const Ort::Exception& e){std::cerr<<"ORT error "<<e.GetOrtErrorCode()<<": "<<e.what()<<"\n";return 2;}catch(const std::exception& e){std::cerr<<"error: "<<e.what()<<"\n";return 3;}}
